package org.diy.liferecorder;
import android.app.*;import android.content.*;import android.os.*;
/** Visible, user-authorized local processing independent of JobScheduler start quotas. */
public final class OfflineRunService extends Service {
 static volatile boolean running;private volatile boolean stopped;private PowerManager.WakeLock wake;private boolean manualOnly;private final Handler updates=new Handler();
 private Notification notification(){PendingIntent open=PendingIntent.getActivity(this,83,new Intent(this,TaskCenterActivity.class),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);PendingIntent stop=PendingIntent.getService(this,84,new Intent(this,OfflineRunService.class).setAction("stop"),PendingIntent.FLAG_IMMUTABLE|PendingIntent.FLAG_UPDATE_CURRENT);Notification.Builder b=new Notification.Builder(this,"offline-active").setSmallIcon(R.drawable.ic_record).setContentTitle(AppLanguage.text(this,"正在手机本地处理")).setContentText(AppLanguage.text(this,OfflineProcessor.status)).setContentIntent(open).setOngoing(true).addAction(0,AppLanguage.text(this,"暂停"),stop);try(RecordStore db=new RecordStore(this)){org.json.JSONArray a=db.rows("SELECT * FROM jobs WHERE id=?",OfflineProcessor.activeId);if(a.length()>0){org.json.JSONObject j=a.getJSONObject(0);long total=j.optLong("progress_total"),done=j.optLong("progress_done");b.setContentText(AppLanguage.text(this,TaskProgress.describe(j))).setProgress(1000,total>0?(int)Math.min(1000,done*1000/total):0,total==0);}}catch(Exception ignored){}return b.build();}
 private final Runnable tick=new Runnable(){public void run(){if(!running)return;if(wake!=null&&!wake.isHeld())wake.acquire(10*60*1000L);((NotificationManager)getSystemService(NOTIFICATION_SERVICE)).notify(83,notification());updates.postDelayed(this,750);}};
 public void onCreate(){super.onCreate();wake=((PowerManager)getSystemService(POWER_SERVICE)).newWakeLock(PowerManager.PARTIAL_WAKE_LOCK,"MindPebble:offline");NotificationManager n=(NotificationManager)getSystemService(NOTIFICATION_SERVICE);n.createNotificationChannel(new NotificationChannel("offline-active","离线处理进度",NotificationManager.IMPORTANCE_LOW));startForeground(83,notification());}
 public int onStartCommand(Intent intent,int flags,int id){if(intent!=null&&"stop".equals(intent.getAction())){getSharedPreferences("offline-scheduling",0).edit().putBoolean("paused",true).apply();stopped=true;if(!running){stopForeground(true);stopSelf();}return START_NOT_STICKY;}if(running)return START_NOT_STICKY;running=true;stopped=false;wake.acquire(10*60*1000L);manualOnly=intent==null||intent.getBooleanExtra("manual_only",true);updates.post(tick);new Thread(()->{try{while(OfflineProcessor.busy()&&!stopped)Thread.sleep(250);if(!stopped)OfflineProcessor.drain(this,manualOnly,()->stopped);}catch(Exception ignored){}finally{if(wake!=null&&wake.isHeld())wake.release();running=false;updates.removeCallbacks(tick);OfflineScheduler.schedule(this);stopForeground(true);stopSelf();}},"visible-offline-speech").start();return START_NOT_STICKY;}
 public void onDestroy(){stopped=true;updates.removeCallbacksAndMessages(null);super.onDestroy();}public IBinder onBind(Intent i){return null;}
}
